import { AIRFIELD_BOUNDS } from './airport-catalogue.ts';
import { CONTACT_RELEASE_NM, SHARED_NAME_AIRPORTS, type CoverageGrid } from './airport-contact.ts';

/** Build-time airport-contact data (generated by app/com-contact-data.ts from hash-pinned inputs). */
export interface ComContactData {
  inputs: { com_sha256: string; airports_sha256: string; world_catalogue_sha256: string; world_source_commit: string; world_retrieved: string };
  coverage: CoverageGrid;
  regionalNames: ReadonlyMap<string, number>;
}
const MAX_BYTES = 65536;
const hash = (value: unknown) => typeof value === 'string' && /^[a-f0-9]{64}$/.test(value);

/** Validates untrusted JSON; throws on any structural mismatch. */
export function parseComContactData(input: unknown): ComContactData {
  const fail = (what: string): never => { throw new Error(`Invalid airport contact data: ${what}`); };
  if (!input || typeof input !== 'object') fail('root');
  const v = input as Record<string, any>;
  if (v.schema !== 1 || v.id !== 'airport-com-contact-v1') fail('identity');
  const i = v.inputs ?? {};
  if (![i.com_sha256, i.airports_sha256, i.world_catalogue_sha256].every(hash) || typeof i.world_source_commit !== 'string'
    || !/^[a-f0-9]{40}$/.test(i.world_source_commit) || typeof i.world_retrieved !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(i.world_retrieved)) fail('inputs');
  const c = v.coverage ?? {};
  if (!Array.isArray(c.bounds) || c.bounds.join(',') !== AIRFIELD_BOUNDS.join(',') || c.cell_deg !== 0.25
    || typeof c.radius_nm !== 'number' || c.radius_nm < CONTACT_RELEASE_NM || !Array.isArray(c.rows)) fail('coverage');
  const [west, south, east, north] = AIRFIELD_BOUNDS;
  const cols = Math.round((east - west) / c.cell_deg), rows = Math.round((north - south) / c.cell_deg);
  if (c.rows.length !== rows || !c.rows.every((row: unknown) => typeof row === 'string' && row.length === cols && /^[01]+$/.test(row))
    || c.complete_cells !== c.rows.join('').split('').filter((x: string) => x === '1').length) fail('coverage rows');
  if (v.shared_name_airports !== SHARED_NAME_AIRPORTS || !Array.isArray(v.regional_names) || v.regional_names.length > 5000) fail('regional names');
  const regionalNames = new Map<string, number>();
  for (const entry of v.regional_names) {
    if (!Array.isArray(entry) || typeof entry[0] !== 'string' || !entry[0] || entry[0].length > 200 || !Number.isInteger(entry[1])
      || entry[1] < SHARED_NAME_AIRPORTS || regionalNames.has(entry[0])) fail('regional name');
    regionalNames.set(entry[0], entry[1]);
  }
  return { inputs: { com_sha256: i.com_sha256, airports_sha256: i.airports_sha256, world_catalogue_sha256: i.world_catalogue_sha256,
    world_source_commit: i.world_source_commit, world_retrieved: i.world_retrieved },
  coverage: { bounds: AIRFIELD_BOUNDS, cell_deg: c.cell_deg, radius_nm: c.radius_nm, rows: [...c.rows] }, regionalNames };
}

export async function loadComContactData(signal?: AbortSignal): Promise<ComContactData> {
  const requestSignal = signal ? AbortSignal.any([signal, AbortSignal.timeout(15000)]) : AbortSignal.timeout(15000);
  const response = await fetch('/airports/com-contact.json', { signal: requestSignal, redirect: 'error' });
  if (!response.ok || Number(response.headers.get('content-length') || 0) > MAX_BYTES) throw new Error('Airport contact data unavailable');
  const bytes = await response.arrayBuffer();
  if (bytes.byteLength > MAX_BYTES) throw new Error('Airport contact data too large');
  return parseComContactData(JSON.parse(new TextDecoder().decode(bytes)));
}
